            fmat.baseColor = Math::Vector3(0.3f, 0.2f, 0.1f);
            m_World->AddComponent<ECS::MeshComponent>(fire, Renderer::MeshFactory::CreateCube(1.0f));
            auto& pe = m_World->AddComponent<ECS::ParticleEmitterComponent>(fire);
