            ECS::Entity wallR = m_World->CreateEntity();
            m_World->AddComponent<ECS::NameComponent>(wallR, "Shelter Wall Right");
            auto& wrt = m_World->AddComponent<ECS::TransformComponent>(wallR);
            wrt.position = Math::Vector3(7.0f, 1.25f, -5.0f);
