            em.baseColor = Math::Vector3(0.6f, 0.1f, 0.4f);
            m_World->AddComponent<ECS::MeshComponent>(enemy, Renderer::MeshFactory::CreateCapsule2D(0.6f, 1.0f));
            m_World->AddComponent<ECS::Sprite2DComponent>(enemy);
