void EditorLayer::SaveCustomTemplate(const std::string& name) {
    if (!m_World) return;

    // Create templates directory next to the executable
    std::filesystem::path templateDir = "templates";
    std::filesystem::create_directories(templateDir);

    // Sanitize name for filename
    std::string safeName = name;
    for (char& c : safeName) {
        if (c == ' ' || c == '/' || c == '\\' || c == ':' || c == '*' ||
            c == '?' || c == '"' || c == '<' || c == '>' || c == '|') {
            c = '_';
        }
    }

    std::string filepath = (templateDir / (safeName + ".enjin")).string();

    Scene::SceneSerializer serializer(m_World);
    Scene::SerializationOptions opts;
    opts.includeVertexData = true;
    auto result = serializer.Save(filepath, opts);

    if (result.success) {
        // Add to the custom templates list if not already present
        bool found = false;
        for (const auto& n : m_CustomTemplateNames) {
            if (n == name) { found = true; break; }
        }
        if (!found) {
            m_CustomTemplateNames.push_back(name);
            m_CustomTemplatePaths.push_back(filepath);
        }
        ENJIN_LOG_INFO(Editor, "Saved custom template: %s -> %s", name.c_str(), filepath.c_str());
    }
}

void EditorLayer::LoadCustomTemplates() {
    m_CustomTemplateNames.clear();
    m_CustomTemplatePaths.clear();

    std::filesystem::path templateDir = "templates";
    if (!std::filesystem::exists(templateDir)) return;

    for (const auto& entry : std::filesystem::directory_iterator(templateDir)) {
        if (entry.is_regular_file() && entry.path().extension() == ".enjin") {
            std::string name = entry.path().stem().string();
            // Replace underscores with spaces for display
            for (char& c : name) {
                if (c == '_') c = ' ';
            }
            m_CustomTemplateNames.push_back(name);
            m_CustomTemplatePaths.push_back(entry.path().string());
        }
    }

    if (!m_CustomTemplateNames.empty()) {
        ENJIN_LOG_INFO(Editor, "Found %zu custom templates", m_CustomTemplateNames.size());
    }
}

void EditorLayer::DrawTemplateCreatorWindow() {
    ImGui::SetNextWindowSize(ImVec2(520, 600), ImGuiCond_FirstUseEver);
    if (!ImGui::Begin("Template Creator", &m_ShowTemplateCreator)) {
        ImGui::End();
        return;
    }

    // Rescan custom templates when needed
    if (m_TmplNeedsRescan) {
        m_ScannedTemplates = Editor::TemplateCreator::ScanTemplates("templates");
        m_TmplNeedsRescan = false;
        m_TmplDeleteConfirm = -1;
    }

    // --- Save Section ---
    if (ImGui::CollapsingHeader("Save Current Scene as Template", ImGuiTreeNodeFlags_DefaultOpen)) {
        ImGui::InputText("Name", m_TmplName, sizeof(m_TmplName));
        ImGui::InputTextMultiline("Description", m_TmplDescription, sizeof(m_TmplDescription),
                                  ImVec2(-1, 60));
        ImGui::InputText("Author", m_TmplAuthor, sizeof(m_TmplAuthor));

        const char* categoryNames[] = { "2D", "3D", "Multiplayer", "Tools" };
        ImGui::Combo("Category", &m_TmplCategory, categoryNames, IM_ARRAYSIZE(categoryNames));

        ImGui::ColorEdit4("Accent Color", m_TmplAccentColor,
                          ImGuiColorEditFlags_NoInputs | ImGuiColorEditFlags_AlphaPreview);

        ImGui::InputText("Thumbnail (PNG)", m_TmplThumbnailPath, sizeof(m_TmplThumbnailPath));
        if (ImGui::IsItemHovered()) {
            ImGui::SetTooltip("Optional path to a PNG thumbnail image for this template");
        }

        ImGui::Spacing();

        bool canSave = m_World && m_TmplName[0] != '\0';
        if (!canSave) ImGui::BeginDisabled();

        if (ImGui::Button("Save as Template", ImVec2(-1, 32))) {
            const char* categoryNames2[] = { "2D", "3D", "Multiplayer", "Tools" };
            Editor::TemplateMetadata meta;
            meta.name = m_TmplName;
            meta.description = m_TmplDescription;
            meta.author = m_TmplAuthor;
            meta.category = categoryNames2[m_TmplCategory];
            meta.accentColor = Math::Vector4(m_TmplAccentColor[0], m_TmplAccentColor[1],
                                             m_TmplAccentColor[2], m_TmplAccentColor[3]);
            meta.thumbnailPath = m_TmplThumbnailPath;

            Scene::SceneSerializer serializer(m_World);
            if (Editor::TemplateCreator::SaveTemplate("templates", meta, m_World, serializer)) {
                // Auto-capture thumbnail from game view render target
                if (m_GameViewRenderTarget && m_GameViewRenderTarget->IsValid()) {
                    auto pixels = m_GameViewRenderTarget->CaptureToPixels();
                    if (!pixels.empty()) {
                        std::string tmplId = meta.id.empty() ? meta.name : meta.id;
                        // Sanitize id same way TemplateCreator does
                        for (auto& c : tmplId) { if (c == ' ') c = '_'; c = static_cast<char>(std::tolower(c)); }
                        Editor::TemplateCreator::SaveThumbnail("templates", tmplId,
                            pixels.data(), m_GameViewRenderTarget->GetWidth(), m_GameViewRenderTarget->GetHeight());
                    }
                }
                m_ConsoleLog.push_back("[Template] Saved: " + meta.name);
                ShowNotification("Template saved: " + std::string(m_TmplName), NotificationType::Success);
                m_TmplNeedsRescan = true;
            } else {
                m_ConsoleLog.push_back("[Template] ERROR: Failed to save template");
            }
        }

        if (!canSave) ImGui::EndDisabled();
    }

    ImGui::Spacing();
    ImGui::Separator();
    ImGui::Spacing();

    // --- Existing Templates Section ---
    if (ImGui::CollapsingHeader("Custom Templates", ImGuiTreeNodeFlags_DefaultOpen)) {
        if (m_ScannedTemplates.empty()) {
            ImGui::TextDisabled("No custom templates found in 'templates/' directory.");
        }

        for (i32 i = 0; i < static_cast<i32>(m_ScannedTemplates.size()); ++i) {
            const auto& tmpl = m_ScannedTemplates[i];
            ImGui::PushID(i);

            // Accent color bar
            ImVec4 accent(tmpl.accentColor.x, tmpl.accentColor.y,
                          tmpl.accentColor.z, tmpl.accentColor.w);
            ImGui::PushStyleColor(ImGuiCol_Header, accent);
            ImGui::PushStyleColor(ImGuiCol_HeaderHovered,
                ImVec4(accent.x * 1.2f, accent.y * 1.2f, accent.z * 1.2f, accent.w));

            bool nodeOpen = ImGui::TreeNode("##tmpl", "%s", tmpl.name.c_str());

            ImGui::PopStyleColor(2);

            // Category badge
            if (!tmpl.category.empty()) {
                ImGui::SameLine();
                ImGui::TextDisabled("[%s]", tmpl.category.c_str());
            }

            if (nodeOpen) {
                if (!tmpl.description.empty()) {
                    ImGui::TextWrapped("%s", tmpl.description.c_str());
                }
                if (!tmpl.author.empty()) {
                    ImGui::TextDisabled("Author: %s", tmpl.author.c_str());
                }
                ImGui::TextDisabled("ID: %s", tmpl.id.c_str());

                ImGui::Spacing();

                if (ImGui::Button("Load", ImVec2(80, 0))) {
                    if (m_World) {
                        Editor::TemplateMetadata loadedMeta;
                        std::string templatePath = (std::filesystem::path("templates") / tmpl.id).string();
                        Scene::SceneSerializer serializer(m_World);
                        if (Editor::TemplateCreator::LoadTemplate(templatePath, m_World, serializer, loadedMeta)) {
                            m_ConsoleLog.push_back("[Template] Loaded: " + loadedMeta.name);
                            m_CurrentScenePath.clear();
                        } else {
                            m_ConsoleLog.push_back("[Template] ERROR: Failed to load template");
                        }
                    }
                }

                ImGui::SameLine();

                // Delete with confirmation
                if (m_TmplDeleteConfirm == i) {
                    ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.7f, 0.15f, 0.15f, 1.0f));
                    if (ImGui::Button("Confirm Delete", ImVec2(120, 0))) {
                        if (Editor::TemplateCreator::DeleteTemplate("templates", tmpl.id)) {
                            m_ConsoleLog.push_back("[Template] Deleted: " + tmpl.name);
                            m_TmplNeedsRescan = true;
                        }
                        m_TmplDeleteConfirm = -1;
                    }
                    ImGui::PopStyleColor();
                    ImGui::SameLine();
                    if (ImGui::Button("Cancel##del", ImVec2(60, 0))) {
                        m_TmplDeleteConfirm = -1;
                    }
                } else {
                    if (ImGui::Button("Delete", ImVec2(80, 0))) {
                        m_TmplDeleteConfirm = i;
                    }
                }

                ImGui::TreePop();
            }

            ImGui::PopID();
        }
    }

    ImGui::Spacing();
    ImGui::Separator();
    ImGui::Spacing();

    // --- Builtin Templates (read-only list) ---
    if (ImGui::CollapsingHeader("Built-in Templates (read-only)")) {
        ImGui::TextDisabled("These templates ship with the engine and cannot be modified.");
        ImGui::Spacing();

        // List the builtin template names (same ones used in the Project Hub wizard)
        const char* builtinNames[] = {
            "empty", "platformer", "topdown2d", "thirdperson", "firstperson",
            "isometric", "rpg_village", "narrative", "savesystem", "visualscript",
            "uicanvas", "bullethell", "idleclicker", "pointclick", "ps1rpg",
            "visualnovel", "gamemanager", "citybuilder", "fpsarena", "teamsports",
            "towerdefense", "runner", "flower", "fixedcam", "metroidvania",
            "vampsurvivor", "roguelike", "soulslike", "couchcoop", "justtwo", "shadowtest",
            "flash_td", "flash_dress", "flash_escape", "flash_rhythm"
        };

        for (const char* name : builtinNames) {
            ImGui::BulletText("%s", name);
        }
    }

    if (ImGui::Button("Refresh", ImVec2(-1, 0))) {
        m_TmplNeedsRescan = true;
    }

    ImGui::End();
}

// ============================================================================
// Template Marketplace Window
// ============================================================================
void EditorLayer::DrawTemplateMarketplaceWindow() {
    ImGui::SetNextWindowSize(ImVec2(680, 550), ImGuiCond_FirstUseEver);
    bool open = m_TemplateMarketplace.IsOpen();
    if (!ImGui::Begin("Template Marketplace", &open)) {
        ImGui::End();
        m_TemplateMarketplace.SetOpen(open);
        return;
    }
    m_TemplateMarketplace.SetOpen(open);

    // Search bar
    ImGui::SetNextItemWidth(ImGui::GetContentRegionAvail().x * 0.6f);
    ImGui::InputTextWithHint("##mktsearch", "Search templates...", m_MarketSearchBuf, sizeof(m_MarketSearchBuf));
    ImGui::SameLine();

    // Category filter
    const char* categories[] = { "All", "Starter", "Genre", "Systems", "Retro", "Advanced" };
    ImGui::SetNextItemWidth(100.0f);
    ImGui::Combo("##mktcat", &m_MarketCategoryFilter, categories, 6);
    ImGui::SameLine();

    // Sort
    const char* sortOpts[] = { "Name", "Rating", "Downloads" };
    ImGui::SetNextItemWidth(90.0f);
    ImGui::Combo("##mktsort", &m_MarketSortBy, sortOpts, 3);

    ImGui::Separator();

    // Get filtered results
    std::string catFilter = m_MarketCategoryFilter > 0 ? categories[m_MarketCategoryFilter] : "";
    auto results = m_TemplateMarketplace.FilterAndSearch(m_MarketSearchBuf, catFilter);

    // Sort results
    if (m_MarketSortBy == 1) { // Rating
        std::sort(results.begin(), results.end(),
            [](const Editor::MarketplaceEntry* a, const Editor::MarketplaceEntry* b) {
                return a->rating > b->rating;
            });
    } else if (m_MarketSortBy == 2) { // Downloads
        std::sort(results.begin(), results.end(),
            [](const Editor::MarketplaceEntry* a, const Editor::MarketplaceEntry* b) {
                return a->downloadCount > b->downloadCount;
            });
    }

    if (results.empty()) {
        DrawEmptyState("{ }", "No Templates Found", "Try a different search or category filter");
    } else {
        // Results count
        ImGui::TextDisabled("%zu template%s", results.size(), results.size() == 1 ? "" : "s");
        ImGui::Spacing();

        // Grid/list of templates
        for (auto* entry : results) {
            ImGui::PushID(entry->id.c_str());

            // Accent color bar
            ImVec4 accent(entry->accentColor[0], entry->accentColor[1],
                          entry->accentColor[2], entry->accentColor[3]);
            ImGui::PushStyleColor(ImGuiCol_Header, accent);
            ImGui::PushStyleColor(ImGuiCol_HeaderHovered,
                ImVec4(accent.x * 1.2f, accent.y * 1.2f, accent.z * 1.2f, accent.w));

            bool nodeOpen = ImGui::TreeNode("##mktentry", "%s", entry->name.c_str());
            ImGui::PopStyleColor(2);

            // Badges on same line
            ImGui::SameLine();
            ImGui::TextDisabled("[%s]", entry->category.c_str());
            ImGui::SameLine();
            ImGui::TextDisabled("[%s]", entry->projectMode.c_str());

            // Rating stars + download count
            ImGui::SameLine(ImGui::GetContentRegionAvail().x - 120.0f + ImGui::GetCursorPosX());
            ImGui::TextColored(ImVec4(1.0f, 0.85f, 0.2f, 1.0f), "%.1f", entry->rating);
            ImGui::SameLine();
            ImGui::TextDisabled("(%u)", entry->downloadCount);

            // Install status indicator
            bool installed = m_TemplateMarketplace.IsInstalled(entry->id);
            if (installed) {
                ImGui::SameLine();
                ImGui::TextColored(ImVec4(0.3f, 0.9f, 0.3f, 1.0f), "[OK]");
            }

            if (nodeOpen) {
                // Description
                ImGui::TextWrapped("%s", entry->description.c_str());
                ImGui::Spacing();

                // Metadata
                ImGui::TextDisabled("Author: %s  |  Version: %s  |  License: %s",
                    entry->author.c_str(), entry->version.c_str(), entry->license.c_str());
                ImGui::TextDisabled("Quality: %s  |  Size: %s",
                    Editor::TemplateMarketplace::GetQualityName(entry->quality),
                    entry->fileSizeBytes < 1024 ? (std::to_string(entry->fileSizeBytes) + " B").c_str() :
                    (std::to_string(entry->fileSizeBytes / 1024) + " KB").c_str());

                // Tags
                if (!entry->tags.empty()) {
                    ImGui::TextDisabled("Tags:");
                    ImGui::SameLine();
                    for (usize t = 0; t < entry->tags.size(); ++t) {
                        if (t > 0) ImGui::SameLine();
                        ImGui::SmallButton(entry->tags[t].c_str());
                    }
                }

                ImGui::Spacing();

                // Install / Uninstall buttons
                if (installed) {
                    ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.2f, 0.6f, 0.2f, 1.0f));
                    ImGui::Button("Installed", ImVec2(90, 0));
                    ImGui::PopStyleColor();
                    ImGui::SameLine();
                    ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.6f, 0.15f, 0.15f, 1.0f));
                    if (ImGui::Button("Remove", ImVec2(70, 0))) {
                        m_TemplateMarketplace.Uninstall(entry->id);
                        ShowNotification("Removed: " + entry->name, NotificationType::Info);
                        m_TmplNeedsRescan = true;
                    }
                    ImGui::PopStyleColor();
                } else {
                    ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(0.2f, 0.4f, 0.8f, 1.0f));
                    if (ImGui::Button("Install", ImVec2(90, 0))) {
                        if (m_TemplateMarketplace.Install(entry->id)) {
                            ShowNotification("Installed: " + entry->name, NotificationType::Success);
                            m_TmplNeedsRescan = true;
                        } else {
                            ShowNotification("Failed to install: " + entry->name, NotificationType::Error);
                        }
                    }
                    ImGui::PopStyleColor();
                }

                ImGui::TreePop();
            }

            ImGui::PopID();
        }
    }

    ImGui::End();
}

// ============================================================================
// Notification Toast System
// ============================================================================
void EditorLayer::ShowNotification(const std::string& message, NotificationType type) {
    EditorNotification notif;
    notif.message = message;
    notif.type = type;
    notif.lifetime = (type == NotificationType::Error) ? 5.0f : 3.0f;
    notif.elapsed = 0.0f;
    notif.slideIn = 0.0f;
    m_Notifications.push_back(std::move(notif));
}

void EditorLayer::DrawNotifications(f32 deltaTime) {
    if (m_Notifications.empty()) return;

    ImGuiIO& io = ImGui::GetIO();
    f32 padding = 16.0f;
    f32 toastW = 300.0f;
    f32 toastH = 40.0f;
    f32 spacing = 6.0f;
    f32 startX = io.DisplaySize.x - toastW - padding;
    f32 startY = io.DisplaySize.y - padding;

    ImDrawList* fg = ImGui::GetForegroundDrawList();

    // Update and draw toasts from bottom up
    i32 visibleIdx = 0;
    for (i32 i = static_cast<i32>(m_Notifications.size()) - 1; i >= 0; --i) {
        auto& notif = m_Notifications[i];
        notif.elapsed += deltaTime;

        // Slide-in animation (0 to 1 over 200ms)
        if (notif.slideIn < 1.0f) {
            notif.slideIn += deltaTime * 5.0f;
            if (notif.slideIn > 1.0f) notif.slideIn = 1.0f;
        }

        // Fade out in last 0.5s
        f32 fadeAlpha = 1.0f;
        f32 remaining = notif.lifetime - notif.elapsed;
        if (remaining < 0.5f) {
            fadeAlpha = remaining / 0.5f;
            if (fadeAlpha < 0.0f) fadeAlpha = 0.0f;
        }

        // Slide from right
        f32 slideOffset = (1.0f - notif.slideIn) * (toastW + padding);
        f32 yPos = startY - (toastH + spacing) * (visibleIdx + 1);
        f32 xPos = startX + slideOffset;

        // Background color based on type
        ImU32 bgColor;
        switch (notif.type) {
            case NotificationType::Success: bgColor = IM_COL32(30, 110, 50, static_cast<u8>(220 * fadeAlpha)); break;
            case NotificationType::Warning: bgColor = IM_COL32(140, 110, 20, static_cast<u8>(220 * fadeAlpha)); break;
            case NotificationType::Error:   bgColor = IM_COL32(150, 30, 30, static_cast<u8>(220 * fadeAlpha)); break;
            default:                        bgColor = IM_COL32(40, 60, 90, static_cast<u8>(220 * fadeAlpha)); break;
        }

        ImVec2 p0(xPos, yPos);
        ImVec2 p1(xPos + toastW, yPos + toastH);
        fg->AddRectFilled(p0, p1, bgColor, 6.0f);

        // Type icon
        const char* icon;
        switch (notif.type) {
            case NotificationType::Success: icon = "[OK]"; break;
            case NotificationType::Warning: icon = "[!]"; break;
            case NotificationType::Error:   icon = "[X]"; break;
            default:                        icon = "[i]"; break;
        }

        ImU32 textColor = IM_COL32(255, 255, 255, static_cast<u8>(240 * fadeAlpha));
        fg->AddText(ImVec2(xPos + 10, yPos + 11), textColor, icon);
        fg->AddText(ImVec2(xPos + 40, yPos + 11), textColor, notif.message.c_str());

        visibleIdx++;
    }

    // Remove expired notifications
    m_Notifications.erase(
        std::remove_if(m_Notifications.begin(), m_Notifications.end(),
            [](const EditorNotification& n) { return n.elapsed >= n.lifetime; }),
        m_Notifications.end());
}

// ============================================================================
// Accent Color Picker (with harmony presets)
// ============================================================================
void EditorLayer::DrawAccentColorPicker() {
    bool accentChanged = false;
    auto& ac = m_EditorSettings.accentColors;
    bool settingsChanged = false;

    if (ImGui::Checkbox("Use Custom Accent Colors", &ac.useCustom)) {
        accentChanged = true;
    }

    if (ac.useCustom) {
        // Harmony presets — derive all accent colors from a single primary color
        ImGui::TextDisabled("Quick Presets:");
        struct AccentPreset {
            const char* name;
            f32 r, g, b;
        };
        static const AccentPreset presets[] = {
            {"Default Blue",   0.22f, 0.45f, 0.78f},
            {"Warm Orange",    0.80f, 0.45f, 0.15f},
            {"Forest Green",   0.22f, 0.60f, 0.30f},
            {"Royal Purple",   0.50f, 0.25f, 0.70f},
            {"Crimson Red",    0.75f, 0.18f, 0.22f},
            {"Teal",           0.15f, 0.55f, 0.60f},
        };

        for (i32 i = 0; i < 6; ++i) {
            if (i > 0) ImGui::SameLine();
            auto& p = presets[i];

            // Draw small color swatch button
            ImGui::PushStyleColor(ImGuiCol_Button, ImVec4(p.r, p.g, p.b, 1.0f));
            ImGui::PushStyleColor(ImGuiCol_ButtonHovered, ImVec4(p.r * 1.2f, p.g * 1.2f, p.b * 1.2f, 1.0f));
            ImGui::PushStyleColor(ImGuiCol_ButtonActive, ImVec4(p.r * 0.8f, p.g * 0.8f, p.b * 0.8f, 1.0f));
            if (ImGui::Button(p.name, ImVec2(0, 24))) {
                // Auto-derive all accent colors from primary
                ac.button       = {p.r * 0.7f, p.g * 0.7f, p.b * 0.7f, 1.0f};
                ac.buttonHover  = {p.r, p.g, p.b, 1.0f};
                ac.buttonActive = {p.r * 1.15f, p.g * 1.15f, p.b * 1.15f, 1.0f};
                ac.checkMark    = {p.r * 1.1f, p.g * 1.1f, p.b * 1.1f, 1.0f};
                ac.sliderGrab   = {p.r * 0.9f, p.g * 0.9f, p.b * 0.9f, 1.0f};
                ac.sliderGrabActive = {p.r * 1.2f, p.g * 1.2f, p.b * 1.2f, 1.0f};
                ac.resizeGrip   = {p.r * 0.6f, p.g * 0.6f, p.b * 0.6f, 0.5f};
                ac.textSelected = {p.r * 0.7f, p.g * 0.7f, p.b * 0.7f, 0.5f};
                ac.dragDropTarget = {p.r, p.g, p.b, 0.9f};
                ac.tabActive    = {p.r * 0.65f, p.g * 0.65f, p.b * 0.65f, 1.0f};
                ac.tabHovered   = {p.r * 0.85f, p.g * 0.85f, p.b * 0.85f, 1.0f};
                accentChanged = true;
            }
            ImGui::PopStyleColor(3);
        }

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // Individual color editors (advanced)
        if (ImGui::TreeNode("Fine-Tune Colors")) {
            if (ImGui::ColorEdit4("Button##accent", &ac.button.r)) accentChanged = true;
            if (ImGui::ColorEdit4("Button Hover##accent", &ac.buttonHover.r)) accentChanged = true;
            if (ImGui::ColorEdit4("Button Active##accent", &ac.buttonActive.r)) accentChanged = true;
            if (ImGui::ColorEdit4("Check Mark##accent", &ac.checkMark.r)) accentChanged = true;
            if (ImGui::ColorEdit4("Slider Grab##accent", &ac.sliderGrab.r)) accentChanged = true;
            if (ImGui::ColorEdit4("Slider Grab Active##accent", &ac.sliderGrabActive.r)) accentChanged = true;
            if (ImGui::ColorEdit4("Resize Grip##accent", &ac.resizeGrip.r)) accentChanged = true;
            if (ImGui::ColorEdit4("Text Selected##accent", &ac.textSelected.r)) accentChanged = true;
            if (ImGui::ColorEdit4("Drag & Drop Target##accent", &ac.dragDropTarget.r)) accentChanged = true;
            if (ImGui::ColorEdit4("Tab Active##accent", &ac.tabActive.r)) accentChanged = true;
            if (ImGui::ColorEdit4("Tab Hovered##accent", &ac.tabHovered.r)) accentChanged = true;
            ImGui::TreePop();
        }

        ImGui::Spacing();
        if (ImGui::Button("Reset to Theme Defaults")) {
            ac = AccentColorConfig::DefaultForTheme(m_EditorSettings.theme);
            ac.useCustom = true;
            accentChanged = true;
        }
    }

    if (accentChanged) {
        m_ImGuiLayer->ApplyTheme(m_EditorSettings.theme, &m_EditorSettings.accentColors);
        settingsChanged = true;
    }

    if (settingsChanged) {
        m_EditorSettings.Save();
    }
}

// ============================================================================
// Theme Preview
// ============================================================================
void EditorLayer::DrawThemePreview() {
    ImVec2 previewSize(250.0f, 160.0f);
    ImVec2 pos = ImGui::GetCursorScreenPos();
    ImDrawList* dl = ImGui::GetWindowDrawList();

    // Get current ImGui style for preview
    ImGuiStyle& style = ImGui::GetStyle();

    // Background
    ImU32 windowBg = ImGui::GetColorU32(ImGuiCol_WindowBg);
    ImU32 childBg = ImGui::GetColorU32(ImGuiCol_ChildBg);
    ImU32 border = ImGui::GetColorU32(ImGuiCol_Border);
    ImU32 titleBg = ImGui::GetColorU32(ImGuiCol_TitleBgActive);
    ImU32 headerBg = ImGui::GetColorU32(ImGuiCol_Header);
    ImU32 button = ImGui::GetColorU32(ImGuiCol_Button);
    ImU32 buttonHov = ImGui::GetColorU32(ImGuiCol_ButtonHovered);
    ImU32 text = ImGui::GetColorU32(ImGuiCol_Text);
    ImU32 textDis = ImGui::GetColorU32(ImGuiCol_TextDisabled);
    ImU32 sliderGrab = ImGui::GetColorU32(ImGuiCol_SliderGrab);
    ImU32 frameBg = ImGui::GetColorU32(ImGuiCol_FrameBg);
    ImU32 checkMark = ImGui::GetColorU32(ImGuiCol_CheckMark);

    // Main background
    dl->AddRectFilled(pos, ImVec2(pos.x + previewSize.x, pos.y + previewSize.y), windowBg, 4.0f);
    dl->AddRect(pos, ImVec2(pos.x + previewSize.x, pos.y + previewSize.y), border, 4.0f);

    // Title bar
    dl->AddRectFilled(ImVec2(pos.x + 1, pos.y + 1),
                      ImVec2(pos.x + previewSize.x - 1, pos.y + 22), titleBg, 4.0f, ImDrawFlags_RoundCornersTop);
    dl->AddText(ImVec2(pos.x + 8, pos.y + 4), text, "Preview Panel");

    // Simulated hierarchy tree
    f32 y = pos.y + 28;
    dl->AddRectFilled(ImVec2(pos.x + 6, y), ImVec2(pos.x + previewSize.x * 0.45f, y + 16), headerBg, 2.0f);
    dl->AddText(ImVec2(pos.x + 10, y + 1), text, "Scene Root");
    y += 18;
    dl->AddText(ImVec2(pos.x + 22, y + 1), textDis, "Entity 1");
    y += 16;
    dl->AddText(ImVec2(pos.x + 22, y + 1), textDis, "Entity 2");

    // Simulated inspector section (right half)
    f32 rightX = pos.x + previewSize.x * 0.48f;
    y = pos.y + 28;
    dl->AddRectFilled(ImVec2(rightX, y), ImVec2(pos.x + previewSize.x - 6, y + 16), headerBg, 2.0f);
    dl->AddText(ImVec2(rightX + 4, y + 1), text, "Inspector");
    y += 20;

    // Slider mockup
    dl->AddRectFilled(ImVec2(rightX + 4, y + 2), ImVec2(pos.x + previewSize.x - 10, y + 14), frameBg, 2.0f);
    f32 sliderEnd = rightX + 4 + (pos.x + previewSize.x - 10 - rightX - 4) * 0.6f;
    dl->AddRectFilled(ImVec2(rightX + 4, y + 2), ImVec2(sliderEnd, y + 14), sliderGrab, 2.0f);
    y += 20;

    // Button mockups
    dl->AddRectFilled(ImVec2(rightX + 4, y), ImVec2(rightX + 60, y + 18), button, 3.0f);
    dl->AddText(ImVec2(rightX + 12, y + 2), text, "Apply");
    dl->AddRectFilled(ImVec2(rightX + 64, y), ImVec2(rightX + 124, y + 18), buttonHov, 3.0f);
    dl->AddText(ImVec2(rightX + 72, y + 2), text, "Cancel");
    y += 24;

    // Checkbox mockup
    dl->AddRectFilled(ImVec2(rightX + 4, y), ImVec2(rightX + 16, y + 12), frameBg, 2.0f);
    dl->AddText(ImVec2(rightX + 7, y - 1), checkMark, "x");
    dl->AddText(ImVec2(rightX + 20, y), textDis, "Enabled");

    // Bottom status bar
    f32 barY = pos.y + previewSize.y - 18;
    dl->AddRectFilled(ImVec2(pos.x + 1, barY),
                      ImVec2(pos.x + previewSize.x - 1, pos.y + previewSize.y - 1), childBg, 4.0f, ImDrawFlags_RoundCornersBottom);
    dl->AddText(ImVec2(pos.x + 8, barY + 2), textDis, "Ready");

    // Reserve space
    ImGui::Dummy(previewSize);
}

// ============================================================================
// Keyboard Shortcuts Help Modal
// ============================================================================
void EditorLayer::DrawShortcutsHelpModal() {
    ImGui::SetNextWindowSize(ImVec2(520, 480), ImGuiCond_FirstUseEver);
    if (!ImGui::Begin("Keyboard Shortcuts", &m_ShowShortcutsHelp)) {
        ImGui::End();
        return;
    }

    ImGui::InputTextWithHint("##shortcutsearch", "Search shortcuts...",
                             m_ShortcutSearchBuf, sizeof(m_ShortcutSearchBuf));
    ImGui::Separator();

    struct ShortcutEntry {
        const char* category;
        const char* shortcut;
        const char* description;
    };

    static const ShortcutEntry shortcuts[] = {
        // General
        {"General", "Ctrl+S", "Save scene"},
        {"General", "Ctrl+Z", "Undo"},
        {"General", "Ctrl+Y", "Redo"},
        {"General", "Ctrl+D", "Duplicate selected"},
        {"General", "Delete", "Delete selected entity"},
        {"General", "F", "Focus on selected entity"},
        {"General", "Ctrl+P", "Command Palette"},
        {"General", "Ctrl+Shift+/", "Show this help"},
        // Viewport
        {"Viewport", "1", "Translate gizmo"},
        {"Viewport", "2", "Rotate gizmo"},
        {"Viewport", "3", "Scale gizmo"},
        {"Viewport", "4", "Toggle local/world space"},
        {"Viewport", "W/A/S/D", "Camera movement (hold RMB)"},
        {"Viewport", "Space / E", "Move camera up"},
        {"Viewport", "Q / Ctrl", "Move camera down"},
        {"Viewport", "Shift", "Sprint (faster camera)"},
        {"Viewport", "RMB + Mouse", "Look around"},
        {"Viewport", "MMB", "Orbit (Orbit mode)"},
        // Selection
        {"Selection", "Ctrl+Click", "Toggle entity selection"},
        {"Selection", "Shift+Click", "Range select"},
        {"Selection", "Drag", "Marquee selection"},
        {"Selection", "Escape", "Clear selection"},
        // Play Mode
        {"Play Mode", "Ctrl+P", "Play / Stop"},
        {"Play Mode", "Ctrl+Shift+P", "Pause / Resume"},
        // Editor
        {"Editor", "F1", "Toggle game menu"},
        {"Editor", "F10", "Toggle input action map"},
        {"Editor", "Ctrl+Shift+/", "Keyboard shortcuts help"},
    };

    std::string filter;
    if (m_ShortcutSearchBuf[0] != '\0') {
        filter = m_ShortcutSearchBuf;
        for (auto& c : filter) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    }

    const char* lastCategory = nullptr;
    for (auto& sc : shortcuts) {
        // Filter
        if (!filter.empty()) {
            std::string shortcutLower = sc.shortcut;
            std::string descLower = sc.description;
            std::string catLower = sc.category;
            for (auto& c : shortcutLower) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
            for (auto& c : descLower) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
            for (auto& c : catLower) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
            if (shortcutLower.find(filter) == std::string::npos &&
                descLower.find(filter) == std::string::npos &&
                catLower.find(filter) == std::string::npos) {
                continue;
            }
        }

        // Category header
        if (!lastCategory || std::strcmp(lastCategory, sc.category) != 0) {
            if (lastCategory) ImGui::Spacing();
            ImGui::TextColored(ImVec4(0.6f, 0.8f, 1.0f, 1.0f), "%s", sc.category);
            ImGui::Separator();
            lastCategory = sc.category;
        }

        // Shortcut entry
        ImGui::Text("  %-20s", sc.shortcut);
        ImGui::SameLine(200.0f);
        ImGui::TextDisabled("%s", sc.description);
    }

    ImGui::End();
}

void EditorLayer::DrawDeleteConfirmModal() {
    ImGui::OpenPopup("Delete Entities?");
    ImVec2 center = ImGui::GetMainViewport()->GetCenter();
    ImGui::SetNextWindowPos(center, ImGuiCond_Appearing, ImVec2(0.5f, 0.5f));
    if (ImGui::BeginPopupModal("Delete Entities?", nullptr, ImGuiWindowFlags_AlwaysAutoResize)) {
        usize count = m_PendingDeleteEntities.size();
        if (count == 1) {
            auto* nc = m_World ? m_World->GetComponent<ECS::NameComponent>(m_PendingDeleteEntities[0]) : nullptr;
            std::string name = nc ? nc->name : "Entity " + std::to_string(m_PendingDeleteEntities[0]);
            ImGui::Text("Delete \"%s\"?", name.c_str());
        } else {
            ImGui::Text("Delete %zu entities?", count);
        }
        ImGui::TextDisabled("This can be undone with Ctrl+Z.");
        ImGui::Spacing();
        if (ImGui::Button("Delete", ImVec2(120, 0))) {
            DeleteSelectedEntities();
            m_ShowDeleteConfirm = false;
            m_PendingDeleteEntities.clear();
            ImGui::CloseCurrentPopup();
        }
        ImGui::SameLine();
        if (ImGui::Button("Cancel", ImVec2(120, 0)) || ImGui::IsKeyPressed(ImGuiKey_Escape)) {
            m_ShowDeleteConfirm = false;
            m_PendingDeleteEntities.clear();
            ImGui::CloseCurrentPopup();
        }
        ImGui::EndPopup();
    } else {
        m_ShowDeleteConfirm = false;
        m_PendingDeleteEntities.clear();
    }
}

void EditorLayer::ImportModel(const std::string& path) {
    if (!m_World) {
        ENJIN_LOG_ERROR(Editor, "Cannot import model: no world loaded");
        m_ConsoleLog.push_back("[Error] Cannot import model: no world loaded");
        return;
    }

    // Pre-fill from .enjinasset if re-importing
    if (Assets::AssetMetadata::Exists(path)) {
        Assets::AssetMetadata meta;
        if (meta.Load(path)) {
            m_ImportDialogOptions = meta.importOptions;
        }
    } else {
        m_ImportDialogOptions = Assets::ImportOptions{};
    }

    m_ImportDialogPath = path;
    m_ShowImportDialog = true;

    // Cache file info once on dialog open (avoid per-frame filesystem calls)
    std::filesystem::path filePath(path);
    m_ImportDialogFilename = filePath.filename().string();
    m_ImportDialogExtension = filePath.extension().string();
    m_ImportDialogFileSize = 0;
    try {
        if (std::filesystem::exists(filePath)) {
            m_ImportDialogFileSize = std::filesystem::file_size(filePath);
        }
    } catch (...) {}
    m_ImportDialogIsReimport = Assets::AssetMetadata::Exists(path);

    // Auto-detect source app from file metadata
    m_ImportDialogDetectedApp = Assets::SourceApp::Auto;
    m_ImportDialogScaleFromPreset = false;
    std::string ext = m_ImportDialogExtension;
    std::transform(ext.begin(), ext.end(), ext.begin(), ::tolower);
    if (ext == ".gltf" || ext == ".glb") {
        // Quick parse: load glTF to get generator string
        Assets::GLTFScene tempScene;
        if (Assets::GLTFLoader::Load(path, tempScene)) {
            if (!tempScene.generator.empty()) {
                std::string g = tempScene.generator;
                std::transform(g.begin(), g.end(), g.begin(), ::tolower);
                if (g.find("blender") != std::string::npos) m_ImportDialogDetectedApp = Assets::SourceApp::Blender;
                else if (g.find("maya") != std::string::npos) m_ImportDialogDetectedApp = Assets::SourceApp::Maya;
                else if (g.find("3ds max") != std::string::npos || g.find("3dsmax") != std::string::npos) m_ImportDialogDetectedApp = Assets::SourceApp::Max3ds;
                else if (g.find("houdini") != std::string::npos) m_ImportDialogDetectedApp = Assets::SourceApp::Houdini;
                else if (g.find("cinema") != std::string::npos || g.find("c4d") != std::string::npos) m_ImportDialogDetectedApp = Assets::SourceApp::Cinema4D;
                else if (g.find("zbrush") != std::string::npos) m_ImportDialogDetectedApp = Assets::SourceApp::ZBrush;
                else if (g.find("substance") != std::string::npos) m_ImportDialogDetectedApp = Assets::SourceApp::SubstancePainter;
                else if (g.find("unreal") != std::string::npos) m_ImportDialogDetectedApp = Assets::SourceApp::Unreal;
                else if (g.find("unity") != std::string::npos) m_ImportDialogDetectedApp = Assets::SourceApp::Unity;
                else if (g.find("sketchup") != std::string::npos) m_ImportDialogDetectedApp = Assets::SourceApp::SketchUp;
            }
        }
    }
}

void EditorLayer::DrawImportDialog() {
    ImGui::OpenPopup("Import Settings");

    ImGui::SetNextWindowSize(ImVec2(480, 0), ImGuiCond_Always);
    if (ImGui::BeginPopupModal("Import Settings", nullptr, ImGuiWindowFlags_AlwaysAutoResize)) {
        // File info (cached values — no filesystem calls per frame)
        ImGui::Text("File: %s", m_ImportDialogFilename.c_str());
        ImGui::Text("Format: %s", m_ImportDialogExtension.c_str());

        if (m_ImportDialogFileSize > 0) {
            if (m_ImportDialogFileSize < 1024) {
                ImGui::Text("Size: %llu bytes", (unsigned long long)m_ImportDialogFileSize);
            } else if (m_ImportDialogFileSize < 1024 * 1024) {
                ImGui::Text("Size: %.1f KB", m_ImportDialogFileSize / 1024.0f);
            } else {
                ImGui::Text("Size: %.1f MB", m_ImportDialogFileSize / (1024.0f * 1024.0f));
            }
        }

        // Re-import indicator
        if (m_ImportDialogIsReimport) {
            ImGui::TextColored(ImVec4(0.4f, 0.8f, 1.0f, 1.0f), "(Re-import)");
        }

        ImGui::Separator();
        ImGui::Spacing();

        // --- Source Application ---
        ImGui::Text("Source Application");

        // Build combo label with auto-detect hint
        const char* sourceAppNames[] = {
            "Auto", "Blender", "Maya", "3ds Max", "Houdini", "Cinema 4D",
            "ZBrush", "Substance Painter", "Unreal Engine", "Unity", "SketchUp", "Custom"
        };
        int currentApp = static_cast<int>(m_ImportDialogOptions.sourceApp);

        // Show detected hint
        if (m_ImportDialogDetectedApp != Assets::SourceApp::Auto) {
            ImGui::SameLine();
            ImGui::TextColored(ImVec4(0.5f, 0.8f, 0.5f, 1.0f), "(Detected: %s)",
                               Assets::GetSourceAppName(m_ImportDialogDetectedApp));
        }

        if (ImGui::Combo("##SourceApp", &currentApp, sourceAppNames, IM_ARRAYSIZE(sourceAppNames))) {
            Assets::SourceApp newApp = static_cast<Assets::SourceApp>(currentApp);
            m_ImportDialogOptions.sourceApp = newApp;
            // Auto-fill scale from preset when switching source app
            if (newApp != Assets::SourceApp::Auto && newApp != Assets::SourceApp::Custom) {
                Assets::SourceAppPreset preset = Assets::GetSourceAppPreset(newApp);
                m_ImportDialogOptions.scale = preset.scale;
                m_ImportDialogScaleFromPreset = true;
            }
        }

        // Show read-only preset values when a specific source app is selected
        {
            Assets::SourceApp selectedApp = m_ImportDialogOptions.sourceApp;
            if (selectedApp != Assets::SourceApp::Auto && selectedApp != Assets::SourceApp::Custom) {
                Assets::SourceAppPreset preset = Assets::GetSourceAppPreset(selectedApp);
                ImGui::Indent(16.0f);
                ImGui::PushStyleColor(ImGuiCol_Text, ImVec4(0.6f, 0.6f, 0.6f, 1.0f));
                ImGui::Text("Preset scale: %.4f", preset.scale);
                ImGui::Text("Z-up to Y-up: %s", preset.zUpToYUp ? "Yes" : "No");
                ImGui::Text("Left to right hand: %s", preset.leftToRight ? "Yes" : "No");
                ImGui::PopStyleColor();
                ImGui::Unindent(16.0f);
            }
        }

        ImGui::Checkbox("Apply Axis Conversion", &m_ImportDialogOptions.convertAxes);
        if (ImGui::IsItemHovered()) {
            ImGui::SetTooltip("Automatically convert coordinate system (Z-up to Y-up, handedness) based on source app");
        }

        if (m_ImportDialogOptions.convertAxes) {
            ImGui::Indent(16.0f);
            ImGui::Checkbox("Flip X", &m_ImportDialogOptions.flipX);
            ImGui::SameLine();
            ImGui::Checkbox("Flip Y", &m_ImportDialogOptions.flipY);
            ImGui::SameLine();
            ImGui::Checkbox("Flip Z", &m_ImportDialogOptions.flipZ);
            ImGui::Unindent(16.0f);
        }

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // --- Import Options ---
        ImGui::Text("Import Options");
        ImGui::DragFloat("Scale", &m_ImportDialogOptions.scale, 0.01f, 0.001f, 100.0f, "%.3f");
        ImGui::Checkbox("Import Materials", &m_ImportDialogOptions.importMaterials);
        ImGui::Checkbox("Import Animations", &m_ImportDialogOptions.importAnimations);
        ImGui::Checkbox("Generate Colliders", &m_ImportDialogOptions.generateColliders);
        ImGui::Checkbox("Generate LODs", &m_ImportDialogOptions.generateLODs);
        if (ImGui::IsItemHovered()) {
            ImGui::SetTooltip("Generate Level-of-Detail meshes (can be slow for large models)");
        }

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // --- Texture Search Paths ---
        ImGui::Text("Texture Search Paths");
        auto& searchPaths = m_ImportDialogOptions.textureSearchPaths;
        i32 removeIdx = -1;
        for (i32 i = 0; i < static_cast<i32>(searchPaths.size()); ++i) {
            ImGui::PushID(i);
            ImGui::Text("%s", searchPaths[i].c_str());
            ImGui::SameLine();
            if (ImGui::SmallButton("X")) {
                removeIdx = i;
            }
            ImGui::PopID();
        }
        if (removeIdx >= 0) {
            searchPaths.erase(searchPaths.begin() + removeIdx);
        }
        if (ImGui::SmallButton("+ Add Path...")) {
            // Use nfd or a simple text input — for now, use current model's parent dir as a starting point
            // We'll add a simple text input approach
            searchPaths.push_back("");
        }
        // Editable text input for the last empty entry
        if (!searchPaths.empty() && searchPaths.back().empty()) {
            static char pathBuf[512] = {};
            ImGui::SetNextItemWidth(-1);
            if (ImGui::InputText("##NewTexPath", pathBuf, sizeof(pathBuf),
                                 ImGuiInputTextFlags_EnterReturnsTrue)) {
                if (pathBuf[0] != '\0') {
                    searchPaths.back() = pathBuf;
                    pathBuf[0] = '\0';
                } else {
                    searchPaths.pop_back();
                }
            }
            if (ImGui::IsItemDeactivated() && pathBuf[0] == '\0') {
                searchPaths.pop_back();
            }
        }

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // --- Texture Compression ---
        ImGui::Text("Texture Compression");
        {
            const char* formatNames[] = {
                "None (RGBA8)", "BC1 (DXT1 - RGB)", "BC3 (DXT5 - RGBA)",
                "BC4 (R only)", "BC5 (RG - Normal maps)", "BC7 (High quality RGBA)",
                "ASTC 4x4", "ASTC 6x6", "ASTC 8x8"
            };
            int currentFmt = static_cast<int>(m_ImportDialogOptions.textureCompression.format);
            if (ImGui::Combo("Format##TexCompress", &currentFmt, formatNames, IM_ARRAYSIZE(formatNames))) {
                m_ImportDialogOptions.textureCompression.format = static_cast<Assets::CompressedFormat>(currentFmt);
            }
            if (ImGui::IsItemHovered()) {
                ImGui::SetTooltip("BC1: RGB 4bpp | BC3: RGBA 8bpp | BC5: Normal maps | BC7: Best quality RGBA 8bpp");
            }

            if (m_ImportDialogOptions.textureCompression.format != Assets::CompressedFormat::None) {
                const char* qualityNames[] = { "Fast", "Normal", "High" };
                int currentQuality = static_cast<int>(m_ImportDialogOptions.textureCompression.quality);
                ImGui::Combo("Quality##TexCompress", &currentQuality, qualityNames, IM_ARRAYSIZE(qualityNames));
                m_ImportDialogOptions.textureCompression.quality = static_cast<Assets::CompressionQuality>(currentQuality);

                ImGui::Checkbox("Generate Mipmaps##TexCompress", &m_ImportDialogOptions.textureCompression.generateMipmaps);
                ImGui::Checkbox("sRGB Color Space##TexCompress", &m_ImportDialogOptions.textureCompression.sRGB);

                // Show compression ratio hint
                f32 ratio = Assets::TextureCompressor::CompressionRatio(m_ImportDialogOptions.textureCompression.format);
                u32 bpp = Assets::TextureCompressor::BitsPerPixel(m_ImportDialogOptions.textureCompression.format);
                ImGui::TextDisabled("%s: %u bpp (%.1fx compression)",
                    Assets::TextureCompressor::FormatName(m_ImportDialogOptions.textureCompression.format),
                    bpp, ratio);
            }
        }

        ImGui::Spacing();
        ImGui::Separator();
        ImGui::Spacing();

        // Buttons
        if (ImGui::Button("Import", ImVec2(120, 0))) {
            // Defer import to next frame so a loading overlay can render first
            m_ImportPending = true;
            m_ImportPendingPath = m_ImportDialogPath;
            m_ImportPendingOptions = m_ImportDialogOptions;
            m_ShowImportDialog = false;
            ImGui::CloseCurrentPopup();
        }
        ImGui::SameLine();
        if (ImGui::Button("Cancel", ImVec2(120, 0))) {
            m_ShowImportDialog = false;
            ImGui::CloseCurrentPopup();
        }

        ImGui::EndPopup();
    }
}

void EditorLayer::DrawImportLoadingOverlay() {
    // Draw a full-viewport overlay so the user sees feedback while the import blocks
    ImGuiViewport* viewport = ImGui::GetMainViewport();
    ImGui::SetNextWindowPos(viewport->Pos);
    ImGui::SetNextWindowSize(viewport->Size);
    ImGui::SetNextWindowBgAlpha(0.7f);
    ImGui::Begin("##ImportLoading", nullptr,
        ImGuiWindowFlags_NoDecoration | ImGuiWindowFlags_NoInputs |
        ImGuiWindowFlags_NoNav | ImGuiWindowFlags_NoMove |
        ImGuiWindowFlags_NoBringToFrontOnFocus);

    ImVec2 center(viewport->Pos.x + viewport->Size.x * 0.5f,
                  viewport->Pos.y + viewport->Size.y * 0.5f);
    std::string filename = std::filesystem::path(m_ImportPendingPath).filename().string();
    std::string text = "Importing " + filename + "...";
    ImVec2 textSize = ImGui::CalcTextSize(text.c_str());
    ImGui::SetCursorScreenPos(ImVec2(center.x - textSize.x * 0.5f, center.y - textSize.y * 0.5f));
    ImGui::TextColored(ImVec4(1.0f, 1.0f, 1.0f, 1.0f), "%s", text.c_str());

    ImGui::End();
}

void EditorLayer::ExecuteImport(const std::string& path, const Assets::ImportOptions& options) {
    if (!m_World) return;

    Assets::ImportResult result = Assets::SceneImporter::Import(path, m_World, options);

    if (result.success) {
        // Detailed summary log
        std::stringstream ss;
        ss << "[Info] Imported " << result.entities.size() << " entities from "
           << std::filesystem::path(path).filename().string();
        m_ConsoleLog.push_back(ss.str());

        ss.str("");
        ss << "[Info]   Meshes: " << result.meshCount
           << ", Materials: " << result.materialCount
           << ", Animations: " << result.animationCount;
        m_ConsoleLog.push_back(ss.str());

        ss.str("");
        ss << "[Info]   Vertices: " << result.totalVertexCount
           << ", Indices: " << result.totalIndexCount;
        m_ConsoleLog.push_back(ss.str());

        if (!result.texturePathsResolved.empty()) {
            ss.str("");
            ss << "[Info]   Textures resolved: " << result.texturePathsResolved.size();
            m_ConsoleLog.push_back(ss.str());
        }
        if (!result.texturePathsMissing.empty()) {
            ss.str("");
            ss << "[Warn]   Textures missing: " << result.texturePathsMissing.size();
            m_ConsoleLog.push_back(ss.str());
            for (const auto& missing : result.texturePathsMissing) {
                m_ConsoleLog.push_back("  [Warn]     " + missing);
            }
        }
        for (const auto& warning : result.warnings) {
            m_ConsoleLog.push_back("[Warn]   " + warning);
        }

        ENJIN_LOG_INFO(Editor, "Imported %zu entities (%u meshes, %u materials, %u anims, %u verts, %u indices) from %s",
            result.entities.size(), result.meshCount, result.materialCount, result.animationCount,
            result.totalVertexCount, result.totalIndexCount, path.c_str());

        // If the scene has no lights, add a directional light so imported models are visible
        {
            auto lightEntities = m_World->GetEntitiesWithComponent<ECS::LightComponent>();
            if (lightEntities.empty()) {
                ECS::Entity light = m_World->CreateEntity();
                m_World->AddComponent<ECS::NameComponent>(light, "Directional Light");
                auto& xform = m_World->AddComponent<ECS::TransformComponent>(light);
                xform.rotation = Math::Quaternion::FromEuler(Math::Vector3(-45.0f, -45.0f, 0.0f));
                auto& lc = m_World->AddComponent<ECS::LightComponent>(light);
                lc.type = ECS::LightType::Directional;
                lc.color = Math::Vector3(1.0f, 1.0f, 1.0f);
                lc.intensity = 1.5f;
                m_ConsoleLog.push_back("[Info] Added directional light (scene had no lights)");

                // Raise ambient so model is visible from all angles
                if (m_RenderSystem) {
                    m_RenderSystem->SetAmbientIntensity(1.0f);
                    m_RenderSystem->SetAmbientColor(Math::Vector3(0.3f, 0.3f, 0.35f));
                }
            }
        }

        // Log diagnostic info about the imported model
        for (ECS::Entity e : result.entities) {
            auto* mesh = m_World->GetComponent<ECS::MeshComponent>(e);
            auto* xf = m_World->GetComponent<ECS::TransformComponent>(e);
            if (mesh && xf) {
                std::stringstream ds;
                ds << "[Info]   Entity mesh: " << mesh->vertices.size() << " verts, "
                   << mesh->indices.size() << " indices, valid=" << (mesh->IsValid() ? "yes" : "NO")
                   << ", pos=(" << xf->position.x << "," << xf->position.y << "," << xf->position.z << ")"
                   << ", scale=(" << xf->scale.x << "," << xf->scale.y << "," << xf->scale.z << ")";
                m_ConsoleLog.push_back(ds.str());
            }
        }

        // Select the root entity and focus camera on it
        if (result.rootEntity != ECS::INVALID_ENTITY) {
            SelectEntity(result.rootEntity);
            FocusOnEntity(result.rootEntity);
        }

        // Save .enjinasset metadata
        Assets::AssetMetadata meta;
        meta.PopulateFromResult(result, path, options);
        meta.Save(path);

        // Track for re-import
        m_LastImportedModelPath = path;

        ShowNotification("Imported: " + std::filesystem::path(path).filename().string() +
            " (" + std::to_string(result.meshCount) + " meshes)", NotificationType::Success);
    } else {
        std::stringstream ss;
        ss << "[Error] Failed to import: " << result.errorMessage;
        m_ConsoleLog.push_back(ss.str());
        ENJIN_LOG_ERROR(Editor, "Failed to import %s: %s", path.c_str(), result.errorMessage.c_str());
        ShowNotification("Import failed: " + std::filesystem::path(path).filename().string(), NotificationType::Error);
    }
}

void EditorLayer::OnFileDrop(int count, const char** paths) {
    for (int i = 0; i < count; ++i) {
        std::filesystem::path filePath(paths[i]);
        std::string ext = filePath.extension().string();
        // Case-insensitive extension comparison
        std::transform(ext.begin(), ext.end(), ext.begin(),
            [](unsigned char c) { return static_cast<char>(std::tolower(c)); });

        if (ext == ".fbx" || ext == ".obj" || ext == ".gltf" || ext == ".glb" ||
            ext == ".dae" || ext == ".3ds") {
            ENJIN_LOG_INFO(Editor, "Drag-and-drop import: %s", paths[i]);
            m_ConsoleLog.push_back(std::string("[Info] Drag-and-drop import: ") + paths[i]);
            ImportModel(filePath.string());
        } else if (ext == ".enjin") {
            ENJIN_LOG_INFO(Editor, "Drag-and-drop scene open: %s", paths[i]);
            m_ConsoleLog.push_back(std::string("[Info] Drag-and-drop scene open: ") + paths[i]);
            OpenScene(filePath.string());
        } else if (ext == ".png" || ext == ".jpg" || ext == ".jpeg" || ext == ".tga" || ext == ".bmp") {
            // Assign texture to selected entity's material (or all mesh children if container)
            ECS::Entity selected = m_PrimarySelected;
            if (selected != ECS::INVALID_ENTITY && m_World) {
                std::string texPath = filePath.string();

                // Helper: assign texture to a single entity
                auto assignTexture = [&](ECS::Entity e) {
                    auto* mat = m_World->GetComponent<ECS::MaterialComponent>(e);
                    if (mat) {
                        mat->baseColorTexturePath = texPath;
                        mat->baseColorTexture = -1;
                        if (m_RenderSystem) m_RenderSystem->ClearFailedTexture(texPath);
                        return true;
                    }
                    if (m_World->HasComponent<ECS::MeshComponent>(e)) {
                        auto& newMat = m_World->AddComponent<ECS::MaterialComponent>(e);
                        newMat.baseColorTexturePath = texPath;
                        if (m_RenderSystem) m_RenderSystem->ClearFailedTexture(texPath);
                        return true;
                    }
                    return false;
                };

                if (assignTexture(selected)) {
                    ENJIN_LOG_INFO(Editor, "Assigned texture to entity %llu: %s",
                        (unsigned long long)selected, paths[i]);
                    m_ConsoleLog.push_back(std::string("[Info] Texture assigned: ") + paths[i]);
                } else {
                    // Selected entity has no mesh — walk all descendants and apply to mesh children
                    int applied = 0;
                    std::function<void(ECS::Entity)> walkChildren = [&](ECS::Entity e) {
                        auto* ch = m_World->GetComponent<ECS::ChildrenComponent>(e);
                        if (!ch) return;
                        for (ECS::Entity child : ch->children) {
                            if (assignTexture(child)) ++applied;
                            walkChildren(child);
                        }
                    };
                    walkChildren(selected);
                    if (applied > 0) {
                        ENJIN_LOG_INFO(Editor, "Assigned texture to %d mesh children: %s", applied, paths[i]);
                        m_ConsoleLog.push_back(std::string("[Info] Texture assigned to ") +
                            std::to_string(applied) + " mesh children: " + paths[i]);
                    } else {
                        ENJIN_LOG_WARN(Editor, "No mesh entities found for texture: %s", paths[i]);
                        m_ConsoleLog.push_back(std::string("[Warn] Select a mesh entity first, then drop texture: ") + paths[i]);
                    }
                }
            } else {
                ENJIN_LOG_WARN(Editor, "No entity selected for texture drop: %s", paths[i]);
                m_ConsoleLog.push_back(std::string("[Warn] Select an entity first, then drop texture: ") + paths[i]);
            }
        } else {
            ENJIN_LOG_WARN(Editor, "Unsupported file dropped: %s", paths[i]);
            m_ConsoleLog.push_back(std::string("[Warn] Unsupported file type: ") + paths[i]);
        }
    }
}

bool EditorLayer::SceneHasMouseLookController() const {
    if (!m_World) return false;
    if (!m_World->GetEntitiesWithComponent<ECS::FirstPersonController>().empty()) return true;
    if (!m_World->GetEntitiesWithComponent<ECS::ThirdPersonController>().empty()) return true;
    return false;
}

void EditorLayer::HandleViewportPicking() {
    // Don't pick if ImGui wants the mouse (hovering over a panel)
    if (WantsMouseInput()) {
        // Cancel any active marquee if mouse enters a panel
        if (m_MarqueeDragging) {
            m_MarqueeDragging = false;
        }
        return;
    }

    if (!m_World || !m_Camera || !m_Renderer) {
        return;
    }

    Math::Vector2 mousePos = Input::GetMousePosition();
    auto extent = m_Renderer->GetSwapchainExtent();
    if (extent.width == 0 || extent.height == 0) return;

    bool ctrlHeld = Input::IsKeyDown(KeyCode::LeftControl) || Input::IsKeyDown(KeyCode::RightControl);

    // --- Marquee drag handling ---
    if (Input::IsMouseButtonPressed(MouseButton::Left) && !ImGuizmo::IsOver()) {
        // Start potential marquee drag
        m_MarqueeStart = ImVec2(mousePos.x, mousePos.y);
        m_MarqueeEnd = m_MarqueeStart;
        m_MarqueeDragging = true;
    }

    if (m_MarqueeDragging && Input::IsMouseButtonDown(MouseButton::Left)) {
        m_MarqueeEnd = ImVec2(mousePos.x, mousePos.y);
    }

    if (m_MarqueeDragging && !Input::IsMouseButtonDown(MouseButton::Left)) {
        m_MarqueeDragging = false;

        // Check if it was a real drag (> 5 pixels) or just a click
        f32 dx = m_MarqueeEnd.x - m_MarqueeStart.x;
        f32 dy = m_MarqueeEnd.y - m_MarqueeStart.y;
        f32 dragDist = std::sqrt(dx * dx + dy * dy);

        if (dragDist > 5.0f) {
            // Marquee selection
            ImVec2 rectMin(std::min(m_MarqueeStart.x, m_MarqueeEnd.x),
                           std::min(m_MarqueeStart.y, m_MarqueeEnd.y));
            ImVec2 rectMax(std::max(m_MarqueeStart.x, m_MarqueeEnd.x),
                           std::max(m_MarqueeStart.y, m_MarqueeEnd.y));

            if (!ctrlHeld) {
                ClearSelection();
            }
            SelectEntitiesInRect(rectMin, rectMax);
            return;
        }

        // It was a click — fall through to pick logic
        // Double-click detection
        static f64 lastClickTime = 0.0;
        static ECS::Entity lastClickedEntity = ECS::INVALID_ENTITY;
        const f64 doubleClickTime = 0.3;

        ECS::Entity picked = ScenePicker::PickEntity(
            m_World, m_Camera,
            mousePos.x, mousePos.y,
            static_cast<f32>(extent.width), static_cast<f32>(extent.height)
        );

        f64 currentTime = ImGui::GetTime();

        if (picked != ECS::INVALID_ENTITY) {
            if (picked == lastClickedEntity && (currentTime - lastClickTime) < doubleClickTime) {
                FocusOnEntity(picked);
                lastClickedEntity = ECS::INVALID_ENTITY;
            } else {
                if (ctrlHeld) {
                    // Toggle selection
                    if (IsSelected(picked)) {
                        DeselectEntity(picked);
                    } else {
                        SelectEntity(picked, true);
                    }
                } else {
                    SelectEntity(picked);
                }
                lastClickedEntity = picked;
                lastClickTime = currentTime;
                ENJIN_LOG_DEBUG(Editor, "Selected entity %llu", (unsigned long long)picked);
            }
        } else {
            // Clicked on empty space
            if (!ctrlHeld) {
                ClearSelection();
            }
            lastClickedEntity = ECS::INVALID_ENTITY;
        }
    }
}

void EditorLayer::DrawMarqueeRect() {
    if (!m_MarqueeDragging) return;

    f32 dx = m_MarqueeEnd.x - m_MarqueeStart.x;
    f32 dy = m_MarqueeEnd.y - m_MarqueeStart.y;
    f32 dragDist = std::sqrt(dx * dx + dy * dy);
    if (dragDist <= 5.0f) return;

    ImDrawList* dl = ImGui::GetForegroundDrawList();
    dl->AddRect(m_MarqueeStart, m_MarqueeEnd, IM_COL32(100, 150, 255, 200));
    dl->AddRectFilled(m_MarqueeStart, m_MarqueeEnd, IM_COL32(100, 150, 255, 40));
}

void EditorLayer::DrawGizmos() {
    if (m_SelectedEntities.empty() || !m_World || !m_Camera || !m_Renderer) {
        return;
    }

    // Get viewport size
    auto extent = m_Renderer->GetSwapchainExtent();
    if (extent.width == 0 || extent.height == 0) {
        return;
    }

    // Compute gizmo position: centroid for multi-select, entity position for single
    Math::Vector3 gizmoPos(0.0f, 0.0f, 0.0f);
    Math::Quaternion gizmoRot;
    Math::Vector3 gizmoScale(1.0f, 1.0f, 1.0f);
    u32 transformCount = 0;

    if (m_SelectedEntities.size() == 1) {
        auto* transform = m_World->GetComponent<ECS::TransformComponent>(m_PrimarySelected);
        if (!transform) return;
        gizmoPos = transform->position;
        gizmoRot = transform->rotation;
        gizmoScale = transform->scale;
        transformCount = 1;
    } else {
        // Multi-select: centroid position, primary entity rotation for local mode
        for (ECS::Entity e : m_SelectedEntities) {
            auto* t = m_World->GetComponent<ECS::TransformComponent>(e);
            if (t) {
                gizmoPos = gizmoPos + t->position;
                transformCount++;
            }
        }
        if (transformCount == 0) return;
        gizmoPos = gizmoPos * (1.0f / static_cast<f32>(transformCount));
        // Use primary entity's rotation so LOCAL mode gizmo aligns to it
        auto* primaryTransform = m_World->GetComponent<ECS::TransformComponent>(m_PrimarySelected);
        if (primaryTransform) {
            gizmoRot = primaryTransform->rotation;
        }
    }

    // Set ImGuizmo to use the full screen as the viewport
    ImGuizmo::SetOrthographic(m_CameraController && m_CameraController->IsOrthographic());
    ImGuizmo::SetDrawlist(ImGui::GetBackgroundDrawList());
    ImGuizmo::SetRect(0, 0, static_cast<f32>(extent.width), static_cast<f32>(extent.height));

    // Get camera matrices
    Math::Matrix4 viewMat = m_Camera->GetViewMatrix();
    Math::Matrix4 projMat = m_Camera->GetProjectionMatrix();
    projMat.m[5] *= -1.0f; // ImGuizmo expects OpenGL Y-up

    // Build gizmo transform matrix
    Math::Matrix4 entityMat = Math::Matrix4::Translation(gizmoPos) *
                               gizmoRot.ToMatrix() *
                               Math::Matrix4::Scale(gizmoScale);

    // Determine ImGuizmo operation
    ImGuizmo::OPERATION op = ImGuizmo::TRANSLATE;
    switch (m_GizmoOperation) {
        case GizmoOperation::Translate: op = ImGuizmo::TRANSLATE; break;
        case GizmoOperation::Rotate: op = ImGuizmo::ROTATE; break;
        case GizmoOperation::Scale: op = ImGuizmo::SCALE; break;
    }

    ImGuizmo::MODE mode = (m_GizmoSpace == GizmoSpace::Local) ? ImGuizmo::LOCAL : ImGuizmo::WORLD;

    // Snap values
    f32 snapValues[3] = { 0.0f, 0.0f, 0.0f };
    if (m_UseSnap) {
        switch (m_GizmoOperation) {
            case GizmoOperation::Translate:
                snapValues[0] = snapValues[1] = snapValues[2] = m_TranslateSnap; break;
            case GizmoOperation::Rotate:
                snapValues[0] = snapValues[1] = snapValues[2] = m_RotateSnap; break;
            case GizmoOperation::Scale:
                snapValues[0] = snapValues[1] = snapValues[2] = m_ScaleSnap; break;
        }
    }

    // Track gizmo drag start/end for undo/redo
    bool gizmoActive = ImGuizmo::IsUsing();
    if (gizmoActive && !m_GizmoDragging) {
        m_GizmoDragging = true;
        m_GizmoStartTransform = entityMat;
    }

    // Draw and manipulate gizmo
    Math::Matrix4 prevMat = entityMat;
    if (ImGuizmo::Manipulate(viewMat.m, projMat.m, op, mode, entityMat.m,
                              nullptr, m_UseSnap ? snapValues : nullptr)) {
        // Compute delta between old and new gizmo matrix
        f32 newTrans[3], newRot[3], newScale[3];
        ImGuizmo::DecomposeMatrixToComponents(entityMat.m, newTrans, newRot, newScale);
        f32 oldTrans[3], oldRot[3], oldScale[3];
        ImGuizmo::DecomposeMatrixToComponents(prevMat.m, oldTrans, oldRot, oldScale);

        Math::Vector3 deltaPos(newTrans[0] - oldTrans[0], newTrans[1] - oldTrans[1], newTrans[2] - oldTrans[2]);
        Math::Vector3 deltaRot(newRot[0] - oldRot[0], newRot[1] - oldRot[1], newRot[2] - oldRot[2]);
        Math::Vector3 deltaScale(
            oldScale[0] != 0.0f ? newScale[0] / oldScale[0] : 1.0f,
            oldScale[1] != 0.0f ? newScale[1] / oldScale[1] : 1.0f,
            oldScale[2] != 0.0f ? newScale[2] / oldScale[2] : 1.0f);

        if (m_SelectedEntities.size() == 1) {
            // Single entity: apply directly
            auto* transform = m_World->GetComponent<ECS::TransformComponent>(m_PrimarySelected);
            if (transform) {
                transform->position = Math::Vector3(newTrans[0], newTrans[1], newTrans[2]);
                transform->scale = Math::Vector3(newScale[0], newScale[1], newScale[2]);
                f32 rx = Math::Radians(newRot[0]);
                f32 ry = Math::Radians(newRot[1]);
                f32 rz = Math::Radians(newRot[2]);
                transform->rotation = Math::Quaternion(Math::Vector3(0, 1, 0), ry)
                                    * Math::Quaternion(Math::Vector3(1, 0, 0), rx)
                                    * Math::Quaternion(Math::Vector3(0, 0, 1), rz);
                if (m_CollabSystem.IsActive()) {
                    Math::Vector3 euler = transform->rotation.ToEuler();
                    m_CollabSystem.OnTransformChanged(m_PrimarySelected,
                        transform->position, euler, transform->scale);
                }
            }
        } else {
            // Multi-entity: apply delta to all selected
            for (ECS::Entity e : m_SelectedEntities) {
                auto* t = m_World->GetComponent<ECS::TransformComponent>(e);
                if (!t) continue;
                t->position = t->position + deltaPos;
                t->scale = Math::Vector3(t->scale.x * deltaScale.x,
                                         t->scale.y * deltaScale.y,
                                         t->scale.z * deltaScale.z);
                if (deltaRot.x != 0.0f || deltaRot.y != 0.0f || deltaRot.z != 0.0f) {
                    Math::Quaternion dr = Math::Quaternion(Math::Vector3(0,1,0), Math::Radians(deltaRot.y))
                                        * Math::Quaternion(Math::Vector3(1,0,0), Math::Radians(deltaRot.x))
                                        * Math::Quaternion(Math::Vector3(0,0,1), Math::Radians(deltaRot.z));
                    t->rotation = dr * t->rotation;
                }
                if (m_CollabSystem.IsActive()) {
                    Math::Vector3 euler = t->rotation.ToEuler();
                    m_CollabSystem.OnTransformChanged(e, t->position, euler, t->scale);
                }
            }
        }

        // Surface snap: project moved entities onto terrain/sphere surfaces
        if (m_SurfaceSnap && m_GizmoOperation == GizmoOperation::Translate) {
            auto terrainEntities = m_World->GetEntitiesWithComponent<ECS::TerrainComponent>();
            auto gravityEntities = m_World->GetEntitiesWithComponent<ECS::GravityZoneComponent>();

            for (ECS::Entity e : m_SelectedEntities) {
                auto* t = m_World->GetComponent<ECS::TransformComponent>(e);
                if (!t) continue;

                Math::Vector3 bestPos = t->position;
                Math::Vector3 bestNormal(0, 1, 0);
                f32 bestDistSq = FLT_MAX;
                bool foundSurface = false;

                // Check terrain surfaces
                for (ECS::Entity te : terrainEntities) {
                    if (te == e) continue;
                    auto* terrain = m_World->GetComponent<ECS::TerrainComponent>(te);
                    auto* terrainXf = m_World->GetComponent<ECS::TransformComponent>(te);
                    if (!terrain || !terrainXf || terrain->heightmap.empty()) continue;

                    // Convert entity position to terrain-local coordinates
                    Math::Vector3 localPos = t->position - terrainXf->position;
                    f32 gridW = static_cast<f32>(terrain->gridWidth);
                    f32 gridH = static_cast<f32>(terrain->gridHeight);
                    f32 cs = terrain->cellSize;

                    // Terrain grid spans [0, gridWidth*cellSize] x [0, gridHeight*cellSize]
                    f32 fx = localPos.x / cs;
                    f32 fz = localPos.z / cs;
                    if (fx < 0.0f || fx >= gridW - 1.0f || fz < 0.0f || fz >= gridH - 1.0f) continue;

                    // Bilinear interpolation of height
                    u32 ix = static_cast<u32>(fx);
                    u32 iz = static_cast<u32>(fz);
                    f32 fracX = fx - static_cast<f32>(ix);
                    f32 fracZ = fz - static_cast<f32>(iz);

                    f32 h00 = terrain->GetHeight(ix, iz);
                    f32 h10 = terrain->GetHeight(ix + 1, iz);
                    f32 h01 = terrain->GetHeight(ix, iz + 1);
                    f32 h11 = terrain->GetHeight(ix + 1, iz + 1);
                    f32 h = h00 * (1.0f - fracX) * (1.0f - fracZ)
                          + h10 * fracX * (1.0f - fracZ)
                          + h01 * (1.0f - fracX) * fracZ
                          + h11 * fracX * fracZ;

                    Math::Vector3 surfacePos(t->position.x, terrainXf->position.y + h, t->position.z);

                    // Compute normal from heightmap gradient
                    f32 hL = terrain->GetHeight(ix > 0 ? ix - 1 : ix, iz);
                    f32 hR = terrain->GetHeight(ix < terrain->gridWidth - 1 ? ix + 1 : ix, iz);
                    f32 hB = terrain->GetHeight(ix, iz > 0 ? iz - 1 : iz);
                    f32 hF = terrain->GetHeight(ix, iz < terrain->gridHeight - 1 ? iz + 1 : iz);
                    Math::Vector3 normal = Math::Vector3(hL - hR, 2.0f * cs, hB - hF).Normalized();

                    f32 dSq = (surfacePos - t->position).LengthSquared();
                    if (dSq < bestDistSq) {
                        bestDistSq = dSq;
                        bestPos = surfacePos;
                        bestNormal = normal;
                        foundSurface = true;
                    }
                }

                // Check sphere gravity zones
                for (ECS::Entity ge : gravityEntities) {
                    if (ge == e) continue;
                    auto* gz = m_World->GetComponent<ECS::GravityZoneComponent>(ge);
                    auto* gzXf = m_World->GetComponent<ECS::TransformComponent>(ge);
                    if (!gz || !gzXf) continue;
                    if (gz->shape != ECS::GravityZoneShape::Sphere || gz->mode != ECS::GravityZoneMode::Point) continue;

                    Math::Vector3 center = gzXf->position;
                    f32 radius = gz->halfExtents.x;
                    Math::Vector3 dir = t->position - center;
                    f32 dist = dir.Length();
                    if (dist < 0.001f) continue;

                    Math::Vector3 normal = dir * (1.0f / dist);
                    Math::Vector3 surfacePos = center + normal * radius;

                    f32 dSq = (surfacePos - t->position).LengthSquared();
                    if (dSq < bestDistSq) {
                        bestDistSq = dSq;
                        bestPos = surfacePos;
                        bestNormal = normal;
                        foundSurface = true;
                    }
                }

                if (foundSurface) {
                    t->position = bestPos;

                    if (m_SurfaceAlignNormal) {
                        Math::Quaternion oldRotation = t->rotation;
                        Math::Quaternion alignRot = Math::Quaternion::FromToRotation(
                            Math::Vector3(0, 1, 0), bestNormal);

                        // Preserve the entity's existing yaw (facing direction)
                        Math::Vector3 oldForward = oldRotation.Rotate(Math::Vector3(0, 0, 1));
                        Math::Vector3 projForward = oldForward - bestNormal * oldForward.Dot(bestNormal);
                        if (projForward.Length() > 0.001f) {
                            projForward = projForward.Normalized();
                            Math::Vector3 alignedForward = alignRot.Rotate(Math::Vector3(0, 0, 1));
                            Math::Quaternion yawCorrection = Math::Quaternion::FromToRotation(
                                alignedForward, projForward);
                            t->rotation = yawCorrection * alignRot;
                        } else {
                            t->rotation = alignRot;
                        }
                    }
                }
            }
        }
    }

    // Gizmo drag ended - create undo command for primary entity
    if (!gizmoActive && m_GizmoDragging) {
        m_GizmoDragging = false;

        if (m_SelectedEntities.size() == 1) {
            auto* transform = m_World->GetComponent<ECS::TransformComponent>(m_PrimarySelected);
            if (transform) {
                f32 oldT[3], oldR[3], oldS[3];
                ImGuizmo::DecomposeMatrixToComponents(m_GizmoStartTransform.m, oldT, oldR, oldS);

                ECS::TransformComponent oldTransform;
                oldTransform.position = Math::Vector3(oldT[0], oldT[1], oldT[2]);
                oldTransform.scale = Math::Vector3(oldS[0], oldS[1], oldS[2]);
                oldTransform.rotation = Math::Quaternion(Math::Vector3(0,1,0), Math::Radians(oldR[1]))
                                      * Math::Quaternion(Math::Vector3(1,0,0), Math::Radians(oldR[0]))
                                      * Math::Quaternion(Math::Vector3(0,0,1), Math::Radians(oldR[2]));

                auto cmd = std::make_unique<TransformCommand>(m_World, m_PrimarySelected, oldTransform, *transform);
                m_UndoRedo.Execute(std::move(cmd));

                // Record mode: capture keyframe on gizmo drag end
                if (m_FlashTimelineEditor.IsRecordMode() && m_FlashTimelineEditor.GetTimeline()) {
                    m_FlashTimelineEditor.CaptureKeyframe(m_World, m_PrimarySelected);
                }
            }
        }
        // Note: multi-entity undo is not tracked per-entity to keep complexity manageable
    }
}

void EditorLayer::BuildGridMesh() {
    if (!m_Renderer) return;

    bool is2D = m_SceneManager.GetProjectMode() == Scene::ProjectMode::Mode2D;
    f32 halfExtent = m_GridSize * 0.5f;
    f32 step = m_GridSize / static_cast<f32>(m_GridLines);
    i32 halfLines = m_GridLines / 2;

    // Count lines: (gridLines+1) per axis, minus 1 axis line each = regular lines
    // Layout: [regular lines] [X axis] [Y/Z axis]
    u32 regularPerAxis = static_cast<u32>(m_GridLines); // lines excluding i=0
    u32 regularLines = regularPerAxis * 2;
    u32 totalVertices = (regularLines + 2) * 2; // +2 for axis lines, *2 verts per line

    m_GridRegularCount = regularLines * 2;
    m_GridAxisXStart = m_GridRegularCount;
    m_GridAxisZStart = m_GridRegularCount + 2;
    m_GridVertexCount = totalVertices;

    // 24 floats per vertex: pos(3) normal(3) uv(2) color(4) tangent(4) boneWeights(4) boneIndices(4)
    // Must match pipeline vertex stride (sizeof(f32) * 24 = 96 bytes)
    constexpr u32 FLOATS_PER_VERT = 24;
    std::vector<f32> verts(totalVertices * FLOATS_PER_VERT, 0.0f);
    u32 v = 0;

    auto addVert = [&](f32 x, f32 y, f32 z) {
        usize base = static_cast<usize>(v) * FLOATS_PER_VERT;
        verts[base + 0] = x;
        verts[base + 1] = y;
        verts[base + 2] = z;
        verts[base + 4] = 1.0f; // normal Y
        verts[base + 8]  = 1.0f; // vertex color R
        verts[base + 9]  = 1.0f; // vertex color G
        verts[base + 10] = 1.0f; // vertex color B
        verts[base + 11] = 1.0f; // vertex color A
        // boneWeights (base+16..19) and boneIndices (base+20..23) stay zero
        v++;
    };

    if (is2D) {
        // 2D mode: grid in XY plane (Z=0)
        // X-parallel lines (horizontal)
        for (i32 i = -halfLines; i <= halfLines; ++i) {
            if (i == 0) continue;
            f32 y = static_cast<f32>(i) * step;
            addVert(-halfExtent, y, 0.0f);
            addVert( halfExtent, y, 0.0f);
        }
        // Y-parallel lines (vertical)
        for (i32 i = -halfLines; i <= halfLines; ++i) {
            if (i == 0) continue;
            f32 x = static_cast<f32>(i) * step;
            addVert(x, -halfExtent, 0.0f);
            addVert(x,  halfExtent, 0.0f);
        }

        // X axis line (horizontal, at y=0)
        addVert(-halfExtent, 0.0f, 0.0f);
        addVert( halfExtent, 0.0f, 0.0f);

        // Y axis line (vertical, at x=0)
        addVert(0.0f, -halfExtent, 0.0f);
        addVert(0.0f,  halfExtent, 0.0f);
    } else {
        // 3D/Mixed mode: grid in XZ plane (Y=0)
        // X-parallel lines
        for (i32 i = -halfLines; i <= halfLines; ++i) {
            if (i == 0) continue;
            f32 z = static_cast<f32>(i) * step;
            addVert(-halfExtent, 0.0f, z);
            addVert( halfExtent, 0.0f, z);
        }
        // Z-parallel lines
        for (i32 i = -halfLines; i <= halfLines; ++i) {
            if (i == 0) continue;
            f32 x = static_cast<f32>(i) * step;
            addVert(x, 0.0f, -halfExtent);
            addVert(x, 0.0f,  halfExtent);
        }

        // X axis line (at z=0, runs along X)
        addVert(-halfExtent, 0.0f, 0.0f);
        addVert( halfExtent, 0.0f, 0.0f);

        // Z axis line (at x=0, runs along Z)
        addVert(0.0f, 0.0f, -halfExtent);
        addVert(0.0f, 0.0f,  halfExtent);
    }

    usize bufferSize = verts.size() * sizeof(f32);
    m_GridVertexBuffer = std::make_unique<Renderer::VulkanBuffer>(m_Renderer->GetContext());
    m_GridVertexBuffer->Create(bufferSize, Renderer::BufferUsage::Vertex, true);
    m_GridVertexBuffer->UploadData(verts.data(), bufferSize);

    m_BuiltGridSize = m_GridSize;
    m_BuiltGridLines = m_GridLines;
    m_BuiltGridIs2D = is2D;
}

void EditorLayer::DrawGrid() {
    if (!m_ShowGrid || !m_Camera || !m_Renderer || !m_RenderSystem) {
        return;
    }

    bool is2D = m_SceneManager.GetProjectMode() == Scene::ProjectMode::Mode2D;

    // Rebuild mesh when grid settings or orientation change
    if (!m_GridVertexBuffer || m_GridSize != m_BuiltGridSize ||
        m_GridLines != m_BuiltGridLines || is2D != m_BuiltGridIs2D) {
        BuildGridMesh();
    }

    if (!m_GridVertexBuffer || m_GridVertexCount == 0) return;

    // Regular grid lines (gray, semi-transparent)
    m_RenderSystem->RenderGridLines(m_GridVertexBuffer.get(), m_GridRegularCount,
        0, Math::Vector3(0.22f, 0.22f, 0.22f), 0.47f);

    // X axis (red) — same in both modes
    m_RenderSystem->RenderGridLines(m_GridVertexBuffer.get(), 2,
        m_GridAxisXStart, Math::Vector3(0.7f, 0.24f, 0.24f), 0.8f);

    // Second axis: Y (green) in 2D mode, Z (blue) in 3D mode
    if (is2D) {
        m_RenderSystem->RenderGridLines(m_GridVertexBuffer.get(), 2,
            m_GridAxisZStart, Math::Vector3(0.24f, 0.7f, 0.24f), 0.8f);
    } else {
        m_RenderSystem->RenderGridLines(m_GridVertexBuffer.get(), 2,
            m_GridAxisZStart, Math::Vector3(0.24f, 0.24f, 0.7f), 0.8f);
    }
}

void EditorLayer::FocusOnEntity(ECS::Entity entity) {
    if (!m_Camera || !m_CameraController || !m_World) {
        return;
    }
    if (!m_World->IsValid(entity)) return;

    // Get entity transform
    auto* transform = m_World->GetComponent<ECS::TransformComponent>(entity);
    if (!transform) {
        return;
    }

    // Calculate bounding size for appropriate distance
    f32 boundingSize = 2.0f;  // Default size
    Math::Vector3 targetPos = transform->position;

    // If entity has a box collider, use its AABB for accurate sizing
    if (m_World->HasComponent<ECS::BoxColliderComponent>(entity)) {
        auto* collider = m_World->GetComponent<ECS::BoxColliderComponent>(entity);
        boundingSize = Math::Max(collider->size.x, Math::Max(collider->size.y, collider->size.z));
        boundingSize *= Math::Max(transform->scale.x, Math::Max(transform->scale.y, transform->scale.z));
        f32 maxScale = Math::Max(transform->scale.x, Math::Max(transform->scale.y, transform->scale.z));
        targetPos = transform->position + collider->center * maxScale;
    } else if (m_World->HasComponent<ECS::MeshComponent>(entity)) {
        // Estimate from mesh vertices
        auto* mesh = m_World->GetComponent<ECS::MeshComponent>(entity);
        if (mesh && mesh->IsValid()) {
            Math::Vector3 minB(FLT_MAX, FLT_MAX, FLT_MAX);
            Math::Vector3 maxB(-FLT_MAX, -FLT_MAX, -FLT_MAX);
            for (const auto& v : mesh->vertices) {
                if (v.position.x < minB.x) minB.x = v.position.x;
                if (v.position.y < minB.y) minB.y = v.position.y;
                if (v.position.z < minB.z) minB.z = v.position.z;
                if (v.position.x > maxB.x) maxB.x = v.position.x;
                if (v.position.y > maxB.y) maxB.y = v.position.y;
                if (v.position.z > maxB.z) maxB.z = v.position.z;
            }
            Math::Vector3 size = maxB - minB;
            boundingSize = Math::Max(size.x, Math::Max(size.y, size.z));
            boundingSize *= Math::Max(transform->scale.x, Math::Max(transform->scale.y, transform->scale.z));
            Math::Vector3 center = (minB + maxB) * 0.5f;
            f32 maxScale = Math::Max(transform->scale.x, Math::Max(transform->scale.y, transform->scale.z));
            targetPos = transform->position + center * maxScale;
        }
    } else {
        // Container node: scan children for mesh bounds (colliders first, then meshes)
        Math::Vector3 globalMin(FLT_MAX, FLT_MAX, FLT_MAX);
        Math::Vector3 globalMax(-FLT_MAX, -FLT_MAX, -FLT_MAX);
        bool foundChild = false;

        for (ECS::Entity child : ECS::GetChildren(m_World, entity)) {
            auto* childTransform = m_World->GetComponent<ECS::TransformComponent>(child);
            if (!childTransform) continue;

            // Try box collider first
            auto* childCollider = m_World->GetComponent<ECS::BoxColliderComponent>(child);
            if (childCollider) {
                f32 ms = Math::Max(childTransform->scale.x, Math::Max(childTransform->scale.y, childTransform->scale.z));
                Math::Vector3 ctr = childTransform->position + childCollider->center * ms;
                Math::Vector3 half = childCollider->size * 0.5f * ms;
                globalMin.x = Math::Min(globalMin.x, ctr.x - half.x);
                globalMin.y = Math::Min(globalMin.y, ctr.y - half.y);
                globalMin.z = Math::Min(globalMin.z, ctr.z - half.z);
                globalMax.x = Math::Max(globalMax.x, ctr.x + half.x);
                globalMax.y = Math::Max(globalMax.y, ctr.y + half.y);
                globalMax.z = Math::Max(globalMax.z, ctr.z + half.z);
                foundChild = true;
                continue;
            }

            // Fall back to mesh bounds
            auto* childMesh = m_World->GetComponent<ECS::MeshComponent>(child);
            if (childMesh && childMesh->IsValid()) {
                f32 ms = Math::Max(childTransform->scale.x, Math::Max(childTransform->scale.y, childTransform->scale.z));
                for (const auto& v : childMesh->vertices) {
                    Math::Vector3 wp = childTransform->position + v.position * ms;
                    globalMin.x = Math::Min(globalMin.x, wp.x);
                    globalMin.y = Math::Min(globalMin.y, wp.y);
                    globalMin.z = Math::Min(globalMin.z, wp.z);
                    globalMax.x = Math::Max(globalMax.x, wp.x);
                    globalMax.y = Math::Max(globalMax.y, wp.y);
                    globalMax.z = Math::Max(globalMax.z, wp.z);
                }
                foundChild = true;
            }
        }

        if (foundChild) {
            Math::Vector3 size = globalMax - globalMin;
            boundingSize = Math::Max(size.x, Math::Max(size.y, size.z));
            targetPos = (globalMin + globalMax) * 0.5f;
        }
    }

    if (boundingSize < 0.01f) boundingSize = 2.0f;

    // Calculate camera distance based on bounding size
    f32 distance = boundingSize * 2.5f;
    distance = Math::Clamp(distance, 2.0f, 200.0f);

    // Get current camera direction (maintain viewing angle)
    Math::Vector3 cameraForward = m_Camera->GetForward();
    Math::Vector3 newCameraPos = targetPos - cameraForward * distance;

    // Set camera position and update orbit target
    m_Camera->SetPosition(newCameraPos);
    m_Camera->SetLookAt(newCameraPos, targetPos, Math::Vector3(0.0f, 1.0f, 0.0f));

    // Update controller's orbit target and sync orientation
    m_CameraController->SetOrbitTarget(targetPos);
    m_CameraController->SetOrbitDistance(distance);
    m_CameraController->SyncFromCamera();

    ENJIN_LOG_INFO(Editor, "Focused on entity %llu at (%.2f, %.2f, %.2f)",
        (unsigned long long)entity, targetPos.x, targetPos.y, targetPos.z);
}

void EditorLayer::SaveScene(const std::string& path) {
    if (!m_World) {
        ENJIN_LOG_ERROR(Editor, "Cannot save scene: no world loaded");
        m_ConsoleLog.push_back("[Error] Cannot save scene: no world loaded");
        return;
    }

    Scene::SceneSerializer serializer(m_World);
    if (m_RenderSystem) {
        serializer.SetSkyboxConfig(m_RenderSystem->GetSkyboxConfig());
    }

    // Capture current render settings for serialization
    auto renderSettings = Renderer::SceneRenderSettings::CaptureFromRuntime(
        m_RenderSystem, m_PostProcessing ? &m_PostProcessing->GetSettings() : nullptr);
    renderSettings.useProjectDefaults = m_CurrentSceneUsesProjectDefaults;
    serializer.SetRenderSettings(renderSettings);

    auto result = serializer.Save(path);

    if (result.success) {
        m_CurrentScenePath = path;
        usize entityCount = m_World->GetEntityCount();
        std::stringstream ss;
        ss << "[Info] Saved scene to " << path << " (" << entityCount << " entities)";
        m_ConsoleLog.push_back(ss.str());
        ENJIN_LOG_INFO(Editor, "Saved scene to %s (%zu entities)", path.c_str(), entityCount);
        ShowNotification("Scene saved: " + std::filesystem::path(path).filename().string(), NotificationType::Success);

        // Track in recent projects
        m_EditorSettings.AddRecentProject(path);
        m_EditorSettings.Save();
    } else {
        std::stringstream ss;
        ss << "[Error] Failed to save scene: " << result.error;
        m_ConsoleLog.push_back(ss.str());
        ENJIN_LOG_ERROR(Editor, "Failed to save scene to %s: %s", path.c_str(), result.error.c_str());
    }
}

void EditorLayer::OpenScene(const std::string& path) {
    if (!m_World) {
        ENJIN_LOG_ERROR(Editor, "Cannot open scene: no world loaded");
        m_ConsoleLog.push_back("[Error] Cannot open scene: no world loaded");
        return;
    }

    Scene::SceneSerializer serializer(m_World);
    auto result = serializer.Load(path, true); // Clear existing entities

    // Apply loaded skybox config
    if (result.success && m_RenderSystem) {
        m_RenderSystem->SetSkybox(serializer.GetSkyboxConfig());
    }

    // Apply loaded render settings
    if (result.success) {
        const auto& loaded = serializer.GetRenderSettings();
        m_CurrentSceneUsesProjectDefaults = loaded.useProjectDefaults;
        if (loaded.useProjectDefaults) {
            m_SceneManager.GetDefaultRenderSettings().ApplyToRuntime(
                m_RenderSystem, m_PostProcessing ? &m_PostProcessing->GetSettings() : nullptr);
        } else {
            loaded.ApplyToRuntime(
                m_RenderSystem, m_PostProcessing ? &m_PostProcessing->GetSettings() : nullptr);
        }
    }

    if (result.success) {
        m_CurrentScenePath = path;
        ClearSelection();
        m_UndoRedo.Clear();

        // Initialize scene lock manager for this scene
        m_SceneLockManager.SetScenePath(path);

        usize entityCount = result.entities.size();
        std::stringstream ss;
        ss << "[Info] Loaded scene from " << path << " (" << entityCount << " entities)";
        m_ConsoleLog.push_back(ss.str());
        ENJIN_LOG_INFO(Editor, "Loaded scene from %s (%zu entities)", path.c_str(), entityCount);

        // Track in recent projects
        m_EditorSettings.AddRecentProject(path);
        m_EditorSettings.Save();
    } else {
        std::stringstream ss;
        ss << "[Error] Failed to load scene: " << result.error;
        m_ConsoleLog.push_back(ss.str());
        ENJIN_LOG_ERROR(Editor, "Failed to load scene from %s: %s", path.c_str(), result.error.c_str());
    }
}


